Data.Script:
var list;
try { list = typeof vars.tick_counters === "string" ? JSON.parse(vars.tick_counters) : vars.tick_counters; } catch (e) { list = null; }
if (!Array.isArray(list)) list = [];
var ended = [];
var changed = 0;
var next = list.map(function (c) {
  if (!(c && c.roundsLeft > 0)) return c;
  changed = 1;
  var copy = Object.assign({}, c, { roundsLeft: c.roundsLeft - 1 });
  if (copy.roundsLeft === 0) ended.push(c.name);
  return copy;
});
return { tick_newCounters: JSON.stringify(next), tick_changed: changed, tick_hasEnded: ended.length ? 1 : 0, tick_endedText: ended.join(", ") };
